function merge(intervals: number[][]): number[][] {
  // Сортируем по началу: тогда пересекаться могут только соседние интервалы
  intervals.sort((a, b) => a[0] - b[0]);

  const result: number[][] = [];
  for (const [start, end] of intervals) {
    const last = result[result.length - 1];

    if (last && start <= last[1]) {
      // Начинается не позже конца последнего — сливаем, расширяя конец.
      // max нужен, если текущий интервал целиком внутри последнего
      last[1] = Math.max(last[1], end);
    } else {
      // Разрыв — начинаем новый интервал
      result.push([start, end]);
    }
  }

  return result;
}

// Время: O(n log n) — сортировка, проход линейный
// Память: O(n) — ответ (и O(log n) на сортировку)
